questions.reference_query:
select o.order_id, c.contact_name
from customers c
right join orders o on o.customer_id = c.customer_id;

select c.contact_name, o.order_id
from customers c
full outer join orders o on o.customer_id = c.customer_id;

select p.product_name, c.category_name
from products p
full outer join categories c on c.category_id = p.category_id;

select s.company_name, p.product_name
from suppliers s
full outer join products p on p.supplier_id = s.supplier_id;

select cu.contact_name, c.category_name
from customers cu
cross join categories c;

select c.contact_name from customers c
union
select s.contact_name from suppliers s;

select p.product_name from products p
union
select c.category_name from categories c;
